async function api(path){if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('Private connector offline. Start python3 server.py on your personal computer.');let r=await fetch('/api/'+path,{cache:'no-store'});if(!r.headers.get('content-type')?.includes('application/json'))throw Error('Private connector offline. Start python3 server.py.');let j=await r.json();if(!r.ok)throw Error(j.error||'Provider unavailable');return j}
function angel(){$('app').innerHTML=heading('Personal connections','Angel One SmartAPI','Test personal market-data access from the private server.')+'<section class="panel"><div class="row"><h2>Market-data connection</h2><span class="pill">Read only</span></div><div class="fields"><div><small>Connection status</small><h3 id="astat">Checking configuration…</h3></div></div><p id="amsg" class="hint">The test requests an NSE equity quote.</p><button class="primary" id="atest">Test connection</button><details open><summary>Private server setup</summary><p>Install the official Python SmartAPI SDK and its dependencies from requirements.txt. Set ANGEL_API_KEY and ANGEL_ACCESS_TOKEN in the personal server environment. Use a current personal session token. Run <code>python3 server.py</code> and open its localhost address. Credentials stay in the server process.</p></details></section>';let check=async test=>{let version=serial;try{let v=await api(test?'angel/test':'status');if(version!==serial)return;$('astat').textContent=test?'Connected':v.angel?'Configured · test required':'Credentials pending';$('amsg').textContent=test?'Quote received · '+v.checked:'Use Test connection to validate a quote request.'}catch(err){if(version!==serial)return;$('astat').textContent='Disconnected';$('amsg').textContent=err.message}};$('atest').onclick=()=>check(true);check(false)}
const stamp=v=>{if(!v)return 'Unavailable';let d=new Date(/^\d+$/.test(v)?+v:v);return isNaN(d)?String(v):d.toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})+' IST'};
function depth(){$('app').innerHTML=heading('Market microstructure','Live Market Depth','Inspect the latest provider snapshot for an NSE equity.')+'<section class="panel"><div class="row"><h2>Order book</h2><span class="tag">Upstox · full quote</span></div><form id="bookform"><div class="fields">'+input('Search stock ticker','ds','','search','list="stocks" maxlength="40"')+'<datalist id="stocks"></datalist></div><button class="primary">Get latest snapshot</button></form><div id="book">'+empty('Awaiting a snapshot. Configure UPSTOX_ACCESS_TOKEN on your personal server to enable the independent feed.')+'</div></section>';$('ds').oninput=()=>{const q=$('ds').value.trim().toUpperCase();$('stocks').innerHTML=q?groups.flat().filter(s=>s.includes(q)).map(s=>'<option>'+esc(s)+'</option>').join(''):''};let req=0;$('bookform').onsubmit=async e=>{e.preventDefault();let version=serial,n=++req;$('book').innerHTML=note('Requesting snapshot…');try{let q=await api('depth?symbol='+encodeURIComponent($('ds').value.trim().toUpperCase()));if(version!==serial||n!==req)return;let ladder=(levels,name)=>'<div><h3>'+name+' · '+levels.length+' levels</h3>'+table(['Price ₹','Pending orders','Quantity'],levels.map(x=>[fmt(x.price),x.orders??'—',x.quantity??'—']))+'</div>';$('book').innerHTML=metrics([['Last price',q.last_price==null?'—':'₹'+fmt(q.last_price)],['Instrument',esc(q.symbol)]])+note('Snapshot received · Provider timestamp '+esc(stamp(q.timestamp))+' · Fetched '+esc(stamp(q.fetched)))+'<div class="pair">'+ladder(q.buy,'Bids')+ladder(q.sell,'Asks')+'</div><h3>Completed trade activity</h3>'+note('Last reported trade: '+esc(stamp(q.last_trade_time))+' · Quantity: '+(q.last_traded_quantity??'unavailable')+'. Individual trade history unavailable in this snapshot.')}catch(err){if(version===serial&&n===req)$('book').innerHTML=empty('Feed unavailable · '+esc(err.message))}}}

